   228    /*    An array of FT_Short containing the deltas for the affected        */
   229    /*    points.  (This only gets the deltas for one dimension.  It will    */
   230    /*    generally be called twice, once for x, once for y.  When used in   */
   231    /*    cvt table, it will only be called once.)                           */
   232    /*                                                                       */
   233    static FT_Short*
   234    ft_var_readpackeddeltas( FT_Stream  stream,
   235                             FT_ULong   size,
   236                             FT_UInt    delta_cnt )
   237    {
   238      FT_Short  *deltas = NULL;
   239      FT_UInt    runcnt, cnt;
   240      FT_UInt    i, j;
   241      FT_Memory  memory = stream->memory;
   242      FT_Error   error  = FT_Err_Ok;
   243
   244      FT_UNUSED( error );
   245
   246
   247      if ( delta_cnt > size )
   248      {
   249        FT_TRACE1(( "ft_var_readpackeddeltas: number of points too large\n" ));
   250        return NULL;
   251      }
   252
   253      if ( FT_NEW_ARRAY( deltas, delta_cnt ) )
   254        return NULL;
   255
   256      i = 0;
   257      while ( i < delta_cnt )
   258      {
   259        runcnt = FT_GET_BYTE();
   260        cnt    = runcnt & GX_DT_DELTA_RUN_COUNT_MASK;
   261
   262        if ( runcnt & GX_DT_DELTAS_ARE_ZERO )
   263        {
   264          /* `runcnt' zeroes get added */
   265          for ( j = 0; j <= cnt && i < delta_cnt; j++ )
   266            deltas[i++] = 0;
   267        }
   268        else if ( runcnt & GX_DT_DELTAS_ARE_WORDS )
   269        {
   270          /* `runcnt' shorts from the stack */
   271          for ( j = 0; j <= cnt && i < delta_cnt; j++ )
   272            deltas[i++] = FT_GET_SHORT();
   273        }
   274        else
   275        {
   276          /* `runcnt' signed bytes from the stack */
   277          for ( j = 0; j <= cnt && i < delta_cnt; j++ )
